evidence.diff:
@@ -2,3 +2,26 @@
 .price { font-size: 28px; color: #222; margin: 0; }
 .price-currency { font-size: 14px; color: #555; }
 .price-tax { font-size: 13px; color: #555; margin: 2px 0 0; }
+
+/* Layout de la PDP (PDP-142.6): dos columnas en escritorio, una en móvil. */
+.pdp { max-width: 1100px; margin: 0 auto; padding: 20px 16px 160px; overflow-x: hidden; }
+.pdp-row { display: grid; grid-template-columns: minmax(0, 620px) minmax(0, 440px); gap: 40px; }
+.pdp-gallery, .pdp-info { min-width: 0; }
+.pdp-main-image { width: 100%; height: auto; aspect-ratio: 1 / 1; background: #f5f5f5; display: block; }
+.pdp-thumbs { display: flex; gap: 8px; margin-top: 10px; overflow-x: auto; }
+.pdp-thumb { width: 90px; height: 90px; flex: 0 0 auto; cursor: pointer; border: 1px solid #eee; padding: 0; background: none; }
+.pdp-thumb > img { width: 100%; height: 100%; display: block; }
+.pdp-thumb.is-active { border-color: #555; }
+.pdp-buybar { margin-top: 22px; }
+.pdp-add { display: block; width: 100%; min-height: 48px; line-height: 48px; text-align: center; background: #222; color: #fff; cursor: pointer; font-size: 15px; letter-spacing: 1px; border: 0; }
+.pdp-section { margin-top: 40px; }
+.pdp-modal { width: min(520px, calc(100% - 32px)); margin: 120px auto; background: #fff; padding: 24px; }
+
+@media (max-width: 767px) {
+  .pdp { padding: 12px 16px 120px; }
+  .pdp-row { grid-template-columns: 1fr; gap: 16px; }
+  .pdp-thumb { width: 64px; height: 64px; }
+  /* Botón de compra siempre visible, por encima del banner de cookies. */
+  .pdp-buybar { position: fixed; left: 0; right: 0; bottom: 0; margin: 0; padding: 8px 16px calc(8px + env(safe-area-inset-bottom)); background: #fff; box-shadow: 0 -2px 12px rgba(0, 0, 0, 0.12); z-index: 30; }
+  .pdp-add { min-height: 48px; }
+}
